local config = {
  ui_story_31210401_1_dialog_content = "Except for a few more creases here and there, the heavy leather cover and gilded font are no different from before.",
  ui_story_31210401_2_dialog_content = "\"Lumopolis Temple Scriptures\"...",
  ui_story_31210401_3_dialog_content = "Well, now that you've more or less read it, do you remember the story I told you last time?",
  ui_story_31210401_4_dialog_content = "The story you told me last time...",
  ui_story_31210401_5_dialog_content = "Hey, Paloma!",
  ui_story_31210401_6_dialog_content = "Good afternoon. Did you come here to read?",
  ui_story_31210401_7_dialog_content = "Good afternoon.",
  ui_story_31210401_8_dialog_content = "That book in your hand... Is that \"Lumopolis Temple Scriptures\"?",
  ui_story_31210401_9_dialog_content = "Yes.",
  ui_story_31210401_10_dialog_content = "How strange. Why would you want to read such a book all of a sudden?",
  ui_story_31210401_11_dialog_content = "Ahaha... I'm a little embarrassed to say...",
  ui_story_31210401_12_dialog_content = "It's basically because I've never read a book about theology or religion before.",
  ui_story_31210401_13_dialog_content = "Carleen recommended this book to me. She said that almost everyone has a copy in Lumopolis.",
  ui_story_31210401_14_dialog_content = "So, I thought it might be a good idea to use this book as an introduction to religion.",
  ui_story_31210401_15_dialog_content = "I see.",
  ui_story_31210401_16_dialog_content = "Do you actually know what lies within the pages of this book, Caelestite?",
  ui_story_31210401_17_dialog_content = "Erm... Not yet.",
  ui_story_31210401_18_dialog_content = "But I'm guessing it contains some interesting legends or stories?",
  ui_story_31210401_19_dialog_content = "Like the ancient battle of good and evil, the 72 Lost Sons of Light...",
  ui_story_31210401_20_dialog_content = "... or legends of old Lumopolis and the God and Goddess of Light?",
  ui_story_31210401_21_dialog_content = "After all, Lumopolis has so many impressive things to offer, so I'm guessing its religious myths are probably quite elaborate, right?",
  ui_story_31210401_22_dialog_content = "...",
  ui_story_31210401_23_dialog_content = "Why are you looking at me like that? Isn't that what this book is about?",
  ui_story_31210401_24_dialog_content = "Do you really have such high expectations for this book?",
  ui_story_31210401_25_dialog_content = "Well... I suppose I'm looking forward to reading the stories it contains.",
  ui_story_31210401_26_dialog_content = "In that case, let me tell you about Lumopolis Temple Scriptures.",
  ui_story_31210401_27_dialog_content = "Especially the core concepts it seeks to convey.",
  ui_story_31210401_28_dialog_content = "Okay!",
  ui_story_31210401_29_dialog_content = "Let us begin.",
  ui_story_31210401_30_dialog_content = "First of all, to create a story... what does one need?",
  ui_story_31210401_31_dialog_content = "Create? Aren't you going to tell me about the stories in the book?",
  ui_story_31210401_32_dialog_content = "Quiet.",
  ui_story_31210401_33_dialog_content = "You have to understand this, in a place like Lumopolis, we first need to specify the different classes.",
  ui_story_31210401_34_dialog_content = "Thus, the distinction between civilians and nobles emerged.",
  ui_story_31210401_35_dialog_content = "Nobles, of course, hold a very different status from most others. This is an indisputable fact.",
  ui_story_31210401_36_dialog_content = "Now, let's get to the meat of the matter.",
  ui_story_31210401_37_dialog_content = "Our story revolves around two noble families—Family A and Family B.",
  ui_story_31210401_38_dialog_content = "Family A sought to find a way to make their daughter accept the grace of the God of Light.",
  ui_story_31210401_39_dialog_content = "And so, they decided that sending her to the Lumopolis Temple to become a nun would be a wise choice.",
  ui_story_31210401_40_dialog_content = "Chaste, pious, sacred, unaffected by the outside world, and not at all influenced by secular life.",
  ui_story_31210401_41_dialog_content = "So... What do nuns do, exactly?",
  ui_story_31210401_42_dialog_content = "That's a very good question.",
  ui_story_31210401_43_dialog_content = "Nuns must confess their sins, lay deceased Aurorians to rest, and suffer for the Lord's inaction.",
  ui_story_31210401_44_dialog_content = "The most important thing is that they firmly adhere to the beliefs and doctrine of the God of Light.",
  ui_story_31210401_45_dialog_content = "All of a nun's beliefs come from this book—the Lumopolis Temple Scriptures.",
  ui_story_31210401_46_dialog_content = "The young nun understood the doctrine well, and believed that she should maintain her piety to the God of Light and reject amorous advances all her life.",
  ui_story_31210401_47_dialog_content = "Reject amorous advances?",
  ui_story_31210401_48_dialog_content = "Oh... Speaking of love.",
  ui_story_31210401_49_dialog_content = "What is your opinion on the God of Light?",
  ui_story_31210401_50_dialog_content = "Ah! Erm... Well...",
  ui_story_31210401_51_dialog_content = "The God of Light... I always hear people mention that name... I suppose it's...",
  ui_story_31210401_52_dialog_content = "Some kind of powerful god?",
  ui_story_31210401_53_dialog_content = "Do you believe there are gods in this world?",
  ui_story_31210401_54_dialog_content = "Anyway, you clearly know nothing about religion. Let's go on with the story.",
  ui_story_31210401_55_dialog_content = "...",
  ui_story_31210401_56_dialog_content = "Family A and Family B lived in harmony, studying magic together, and relying on each other for mutual benefit.",
  ui_story_31210401_57_dialog_content = "Lumopolis officials are very wary of those who go against the teachings of the God of Light.",
  ui_story_31210401_58_dialog_content = "In order to dispel the concerns of the upper class, the two families conducted their research with complete transparency...",
  ui_story_31210401_59_dialog_content = "Finally, under the guidance of the God of Light, a breakthrough was made.",
  ui_story_31210401_60_dialog_content = "They sang to the heavens, praising the White Night, and reveling in their faith.",
  ui_story_31210401_61_dialog_content = "The fates of the two families were inseparable, forever entwined.",
  ui_story_31210401_62_dialog_content = "The young nun from Family A we mentioned earlier was also very pleased with this revelation.",
  ui_story_31210401_63_dialog_content = "Because she knew that this blessing was truly the will of the God of Light.",
  ui_story_31210401_64_dialog_content = "From then on, her faith became even more resolute, and she vowed to use every waking moment to carry out her duties as a nun.",
  ui_story_31210401_65_dialog_content = "Forever.",
  ui_story_31210401_66_dialog_content = "...",
  ui_story_31210401_67_dialog_content = "What's the matter?",
  ui_story_31210401_68_dialog_content = "You look as though you have something to say.",
  ui_story_31210401_69_dialog_content = "Forever... just seems a little unrealistic.",
  ui_story_31210401_70_dialog_content = "Dejected, the man asked his family if there was any way he could have this nun as his wife.",
  ui_story_31210401_71_dialog_content = "His family told him that if he even thought about marrying a low-level noble, he would be disowned immediately.",
  ui_story_31210401_72_dialog_content = "The man resolutely showed his intention. He didn't care about their shallow concept of status. He only cared about love.",
  ui_story_31210401_73_dialog_content = "As a result, the man lost his noble status and became a civilian.",
  ui_story_31210401_74_dialog_content = "He found the nun, explained the situation to her, and then began courting her once more.",
  ui_story_31210401_75_dialog_content = "In his heart, he was nervous, and was ready for the nun to reject him again...",
  ui_story_31210401_76_dialog_content = "The nun's eyes widened in surprise when she heard that the man was no longer a noble...",
  ui_story_31210401_77_dialog_content = "She accepted his courtship right there on the spot.",
  ui_story_31210401_78_dialog_content = "Since the man had gone against his family, the nun believed she should also go against the temple's doctrine.",
  ui_story_31210401_79_dialog_content = "But... according to the doctrine in this book, the nun shouldn't have gone with him, right?",
  ui_story_31210401_80_dialog_content = "This is a story, and a story about Lumopolis at that. Of course it will have a happy ending.",
  ui_story_31210401_81_dialog_content = "Now, behold this just, glorious, and spectacular ending—",
  ui_story_31210401_82_dialog_content = "The God of Light was moved by the man's courage in defying his family and the piety of the nun who spurned his advances for so long. And so, he gave them the gift of love.",
  ui_story_31210401_83_dialog_content = "From then on, they lived happily ever after and had three children.",
  ui_story_31210401_84_dialog_content = "It's the kind of word you only see in fairy tales.",
  ui_story_31210401_85_dialog_content = "You're right. It is a fairy tale.",
  ui_story_31210401_86_dialog_content = "I didn't think there would be such a dramatic and detailed story in this book!",
  ui_story_31210401_87_dialog_content = "I thought it would just be full of obscure ancient myths.",
  ui_story_31210401_88_dialog_content = "If you wish to know more, I'm afraid you'll have to find out for yourself from the book.",
  ui_story_31210401_89_dialog_content = "Alright, I will!",
  ui_story_31210401_90_dialog_content = "In that case, I'll head back and read it carefully...",
  ui_story_31210401_91_dialog_content = "Thank you for sharing that story, Paloma! I'll tell you what I think of the book once I finish reading it!",
  ui_story_31210401_92_dialog_content = "Last time, you told me a story about a nun and her family!",
  ui_story_31210401_93_dialog_content = "A story about the God of Light's grace, the sincere cooperation between two families, and a happy ending.",
  ui_story_31210401_94_dialog_content = "Well, after listening to my story, you read the book for yourself, didn't you?",
  ui_story_31210401_95_dialog_content = "Would you now think that this book met your expectations?",
  ui_story_31210401_96_dialog_content = "Or did you prefer the God and Goddess of Light?",
  ui_story_31210401_97_dialog_content = "Erm... Well...",
  ui_story_31210401_98_dialog_content = "Actually... I didn't quite get it...",
  ui_story_31210401_99_dialog_content = "This book is just full of complicated religious doctrines... But it did help me get to sleep.",
  ui_story_31210401_100_dialog_content = "Indeed.",
  ui_story_31210401_101_dialog_content = "And... I don't understand how the contents of this book have anything to do with the story you told me last time?",
  ui_story_31210401_102_dialog_content = "There's nothing about a young nun or two families in the book...",
  ui_story_31210401_103_dialog_content = "This book is basically a tribute, singing the praises of the God of Light.",
  ui_story_31210401_104_dialog_content = "This is because that happy tale does not exist.",
  ui_story_31210401_105_dialog_content = "It's just that the last time I saw you looked so excited about reading it, so I told a story that was in line with its core concept.",
  ui_story_31210401_106_dialog_content = "Unfortunately, it is a completely erroneous concept.",
  ui_story_31210401_107_dialog_content = "Now, I hope you're ready to face the reality—",
  ui_story_31210401_108_dialog_content = "After all, the more beautiful a story is, the better it can obscure the darkness of reality.",
  ui_story_31210401_109_dialog_content = "And the better it can convey how laughable this book really is.",
  ui_story_31210401_110_dialog_content = "The darkness of reality?",
  ui_story_31210401_111_dialog_content = "So... That story from last time wasn't just a simple story, was it?",
  ui_story_31210401_112_dialog_content = "Of course it wasn't. Now, I will reveal the dark ending to you.",
  ui_story_31210401_113_dialog_content = "Let us return to the beginning of the \"cooperation\" between Family A and B.",
  ui_story_31210401_114_dialog_content = "Though they possessed similar power, they held diametrically opposed views on how to use that power.",
  ui_story_31210401_115_dialog_content = "In order to achieve their magical breakthrough, Family A committed a contemptible crime.",
  ui_story_31210401_116_dialog_content = "Their shameful deed was eventually made public, the momentum of which was impossible to quash.",
  ui_story_31210401_117_dialog_content = "Lumopolis, in the name of the God of Light, was punished, as were Families A and B.",
  ui_story_31210401_118_dialog_content = "The God of Light abandoned them, as they were unworthy to stand in his glory.",
  ui_story_31210401_119_dialog_content = "This story... sounds familiar...",
  ui_story_31210401_120_dialog_content = "The young nun of Family A was not spared. She was excommunicated from the church.",
  ui_story_31210401_121_dialog_content = "She thought that this would be the full extent of her punishment. She didn't expect fate to have an even more dastardly trick to play on her...",
  ui_story_31210401_122_dialog_content = "The son of Family B was a cruel and deranged young man.",
  ui_story_31210401_123_dialog_content = "Blinded by his noble authority, he vowed to go to any lengths to have his revenge...",
  ui_story_31210401_124_dialog_content = "He drew everyone into his twisted machinations and gave birth to an even greater tragedy.",
  ui_story_31210401_125_dialog_content = "The roles of victim and perpetrator continued to shift and spiral, and the innocent were plunged into an inescapable vortex.",
  ui_story_31210401_126_dialog_content = "Mercy? Understanding? Forgiveness? The nun saw none of these. All she saw was...",
  ui_story_31210401_A1_dialog_content = "A blind ruthlessness that crushed her faith.",
  ui_story_31210401_127_dialog_content = "And so, the nun abided by the Lumopolis Temple Scriptures, only to have her family slain as a result.",
  ui_story_31210401_128_dialog_content = "And now you know. That same book, the very same doctrine—",
  ui_story_31210401_129_dialog_content = "The tale and reality have entirely different endings. Tales are tales, but reality is a different story.",
  ui_story_31210401_130_dialog_content = "And that's all there is to say about this book.",
  ui_story_31210401_131_dialog_content = "Lumopolis Temple Scriptures...",
  ui_story_31210401_132_dialog_content = "You have the strangest look on your face right now... Tell me what is on your mind.",
  ui_story_31210401_133_dialog_content = "I think I see what you're trying to say, Paloma. This nun actually...",
  ui_story_31210401_134_option_content = "Hasn't found her own true faith yet...?",
  ui_story_31210401_135_dialog_content = "Perhaps.",
  ui_story_31210401_136_dialog_content = "But understanding that her previous beliefs were wrong is not wholly a bad thing.",
  ui_story_31210401_137_dialog_content = "Was the tragedy of her past too much for the nun to take?",
  ui_story_31210401_138_option_content = "Have you found your true faith?",
  ui_story_31210401_139_dialog_content = "Do you really believe there is such a thing as true faith in this world?",
  ui_story_31210401_140_dialog_content = "I'm sorry. I... I don't know.",
  ui_story_31210401_141_dialog_content = "That's not important.",
  ui_story_31210401_142_dialog_content = "What is important is that faith must not be a device used by the few to brainwash the many.",
  ui_story_31210401_143_dialog_content = "Faith must come from within.",
  ui_story_31210401_144_dialog_content = "From within...",
  ui_story_31210401_145_dialog_content = "The reality of Lumopolis Temple is far more corrupt than you could possibly imagine.",
  ui_story_31210401_146_dialog_content = "Hanging on to a decaying class system that cannot be crossed within an individual's lifetime.",
  ui_story_31210401_147_dialog_content = "Maybe... the temple is only part of Lumopolis?",
  ui_story_31210401_148_dialog_content = "I've come across both ignorant commoners and principled nobles in Lumopolis.",
  ui_story_31210401_149_dialog_content = "Lumopolis is a vast and complex city. There are so many people in it.",
  ui_story_31210401_A2_dialog_content = "Not merely a single, intangible God of Light.",
  ui_story_31210401_150_dialog_content = "I know that some people aren't happy with the way things are, and are trying to do something about it...",
  ui_story_31210401_151_dialog_content = "... I understand the way you think.",
  ui_story_31210401_152_dialog_content = "But I'm sorry.",
  ui_story_31210401_153_dialog_content = "Those who believe Lumopolis can change fail to perceive the heart of the problem.",
  ui_story_31210401_154_dialog_content = "Its innate structure creates an irreconcilable contradiction.",
  ui_story_31210401_155_dialog_content = "But everyone is entitled to their own opinion... To this, I cannot object.",
  ui_story_31210401_156_dialog_content = "So, hold on to it, your view of the world.",
  ui_story_31210401_157_dialog_content = "Erm... Are you leaving already?",
  ui_story_31210401_158_dialog_content = "Wait, you dropped your coin!",
  ui_story_31210401_159_dialog_content = "Keep it. I'd like to give it to you as a memento of this conversation.",
  ui_story_31210401_160_dialog_content = "Goodbye.",
  ui_story_31210601_1_dialog_content = "Is this the place?",
  ui_story_31210601_2_dialog_content = "That's right, now let's head inside.",
  ui_story_31210601_3_dialog_content = "Regarding Pittman, I've already made arrangements. Are we really gonna do this?",
  ui_story_31210601_4_dialog_content = "Of course. After all, as the second-in-command of the <color=#FFB400>Black Roses</color>, this is also part of your job.",
  ui_story_31210601_5_dialog_content = "As for what happens if you fail to keep your word... Well, I think I've made it perfectly clear to you, right?",
  ui_story_31210601_6_dialog_content = "C-Crystal clear. Just leave it to me.",
  ui_story_31210601_7_dialog_content = "Please wipe your hands first, sir.",
  ui_story_31210601_8_dialog_content = "Alright.",
  ui_story_31210601_9_dialog_content = "(Now all I have to do is pluck a grape and feed it to Paloma.)",
  ui_story_31210601_10_dialog_content = "(I've already rehearsed it in my mind a bunch of times, but it still feels awkward...)",
  ui_story_31210601_11_dialog_content = "Well? What are you waiting for?",
  ui_story_31210601_12_dialog_content = "(S-She grabbed my hand...?!)",
  ui_story_31210601_13_dialog_content = "(She's just feeding herself at this point...)",
  ui_story_31210601_14_dialog_content = "You'll never make it as my second-in-command with such a stiff disposition.",
  ui_story_31210601_15_dialog_content = "I-I'll do better next time.",
  ui_story_31210601_16_dialog_content = "Why are you guys just standing around gawking?! Don't you all have work to do?!",
  ui_story_31210601_17_dialog_content = "Y-Yes!",
  ui_story_31210601_18_dialog_content = "Please use this handkerchief to wipe your hands.",
  ui_story_31210601_19_dialog_content = "And here's a glass of wine. Please enjoy.",
  ui_story_31210601_20_dialog_content = "Now that's more like it. You'll make a wonderful second-in-command at this rate, PlayerName.",
  ui_story_31210601_21_dialog_content = "I'll take that as a compliment...",
  ui_story_31210601_22_dialog_content = "Alright, that will do for now. We shouldn't keep our guest waiting any longer.",
  ui_story_31210601_23_dialog_content = "Hmph. I almost didn't recognize you, Paloma.",
  ui_story_31210601_24_dialog_content = "Joining a gang without a second thought simply in defiance against Lumopolis. Is there no limit to how low you're willing to stoop?",
  ui_story_31210601_25_dialog_content = "Don't forget, you're still a wanted criminal.",
  ui_story_31210601_26_dialog_content = "I'm free to do whatever I want and join whatever group I see fit.",
  ui_story_31210601_27_dialog_content = "Besides, Lumopolis is the worst of the worst in this world. Anyone would be a step up from them!",
  ui_story_31210601_28_dialog_content = "Tell me, did your lackey bring me here just so you could gloat to an old aquaintance about how unrecognizable you've become?",
  ui_story_31210601_29_dialog_content = "I told you last time that I would show you no mercy if we ever met again.",
  ui_story_31210601_30_dialog_content = "You think too highly of yourself, Your Honor. Clearly, you're the one who's been chasing after my heels this entire time.",
  ui_story_31210601_31_dialog_content = "I was willing to let you go, but since you've brought us to this point, it appears I have no choice.",
  ui_story_31210601_32_dialog_content = "Let this be the final tie to Lumopolis that I cut off. Good riddance.",
  ui_story_31210601_33_dialog_content = "Still, I have no reason to deal with someone of your level personally.",
  ui_story_31210601_34_dialog_content = "I'll have my second-in-command show you exactly what happens when you make an enemy of me.",
  ui_story_31210601_35_dialog_content = "Ready for the worst, Your Honor?",
  ui_story_31210601_36_dialog_content = "You intend to send a single crony to fight against a Lumopolis judge?",
  ui_story_31210601_37_dialog_content = "Think you're so tough, huh? Forgive my insolence then.",
  ui_story_31210601_38_dialog_content = "Urgh—!",
  ui_story_31210601_39_dialog_content = "He's out cold, boss.",
  ui_story_31210601_40_dialog_content = "Couldn't even take a single hit, huh? What an eyesore.",
  ui_story_31210601_41_dialog_content = "Tie him up and bring him along for me.",
  ui_story_31210601_42_dialog_content = "Yes, ma'am!",
  ui_story_31210601_43_dialog_content = "Brilliant... simply brilliant! Hahaha!",
  ui_story_31210601_44_dialog_content = "Your strength and cunning put even me to shame, Lady Paloma.",
  ui_story_31210601_45_dialog_content = "You flatter me. I'm just glad my performance didn't disappoint you.",
  ui_story_31210601_46_dialog_content = "How could it have? The Black Roses must truly be something, considering even a second-in-command could take down a judge.",
  ui_story_31210601_47_dialog_content = "Though I have never heard of your gang, I look forward to seeing your exploits in the near future.",
  ui_story_31210601_48_dialog_content = "The Black Roses have always been as aggressive as we are discrete.",
  ui_story_31210601_49_dialog_content = "Isn't this the reason you approached us in the first place?",
  ui_story_31210601_50_dialog_content = "Ah... Your perceptive mind and quick tongue are matched only by your beauty, milady.",
  ui_story_31210601_51_dialog_content = "To be honest, my feud with the Hall of Justice goes back many years. They have always been willing to oppress others with their meaningless rules—even their own people.",
  ui_story_31210601_52_dialog_content = "You heard it yourself just now as well. The Hall of Justice has placed a bounty on my head.",
  ui_story_31210601_53_dialog_content = "Considering our mutual enemy, I believe we can work together quite nicely.",
  ui_story_31210601_54_dialog_content = "It would be my greatest honor to do so.",
  ui_story_31210601_55_dialog_content = "Your praise is appreciated, but let's get down to business, shall we? Tell me more about this job of yours.",
  ui_story_31210601_56_dialog_content = "Straight to the point, I like it!",
  ui_story_31210601_57_dialog_content = "I would like to ask your organization for help in \"purging\" an area under my jurisdiction.",
  ui_story_31210601_58_dialog_content = "Once you finish your work, I will arrive with a retinue of soldiers, we will pretend to do battle, and then my men will let you go.",
  ui_story_31210601_59_dialog_content = "Afterward, we shall return to Lumopolis to treat our injuries. Once there, I'll claim that my domain was attacked by Eclipsites and that we were all but wiped out.",
  ui_story_31210601_60_dialog_content = "You want to purge your own territory of its people?",
  ui_story_31210601_61_dialog_content = "Why would you do something like that to yourself?",
  ui_story_31210601_62_dialog_content = "That barren wasteland has no future as it is now. Being bound to it will only slow me down.",
  ui_story_31210601_63_dialog_content = "I already have a parcel of fertile land in my sights, but it remains in the hands of a political opponent. With this plan, the City Lord will have no choice but to intercede on my behalf.",
  ui_story_31210601_64_dialog_content = "It will be the last purpose that those fools will serve me.",
  ui_story_31210601_66_dialog_content = "<color=#e8d9bb>Clank—</color>",
  ui_story_31210601_67_dialog_content = "Consider this chest of jewels your upfront payment.",
  ui_story_31210601_68_dialog_content = "Should you succeed, I could make you an honorary officer in the city afterwards if you want.",
  ui_story_31210601_69_dialog_content = "The law would be on your side once more; you wouldn't have to live in the shadows anymore.",
  ui_story_31210601_70_dialog_content = "You would never have to work another day either. The people's offerings would be more than enough to sustain us all for the rest of our lives!",
  ui_story_31210601_71_dialog_content = "What do you say? I believe an offer like this requires very little consideration.",
  ui_story_31210601_72_dialog_content = "You can forget about making me an officer. I've always done my work according to how much I'm paid.",
  ui_story_31210601_73_dialog_content = "Besides, I have no interest in establishing any sort of ties with Lumopolis or their rotten systems of governance.",
  ui_story_31210601_74_dialog_content = "You really are different from the rest. Well then, I leave my bright and prosperous future in the hands of the Black Roses.",
  ui_story_31210601_75_dialog_content = "You hypocritical Lumopolis nobles should entrust your futures to the God of Light, not to me.",
  ui_story_31210601_76_dialog_content = "There's nothing special about me.",
  ui_story_31210601_77_dialog_content = "Was it something I said? Or perhaps something about my offer wasn't to your liking?",
  ui_story_31210601_78_dialog_content = "Oh no, your offer was quite reasonable. More than enough for me to secure a bright and prosperous future for myself, in fact.",
  ui_story_31210601_79_dialog_content = "Unfortunately, the only future in store for you is in a Hall of Justice prison cell.",
  ui_story_31210601_80_dialog_content = "What?! You... What is the meaning of this?!",
  ui_story_31210601_81_dialog_content = "Ah... I see! I understand it all now! You two mongrels were working together all along to implicate me! Is that it?!",
  ui_story_31210601_82_dialog_content = "Yes, I remember now! Last time, when I was teaching those commoners a lesson, you were the \"nun\" who attacked me, weren't you? The Black Rose!",
  ui_story_31210601_83_dialog_content = "Such a brilliant disguise. I didn't even recognize you.",
  ui_story_31210601_84_dialog_content = "As for you, Your Honor... You were the one who stopped her from attacking me, if I'm not mistaken?",
  ui_story_31210601_85_dialog_content = "To think, you two were working together all this time just to entrap me...",
  ui_story_31210601_86_dialog_content = "You misunderstand the depth of our cooperation.",
  ui_story_31210601_87_dialog_content = "I only stopped her at the time because, despite your vile behavior, you hadn't violated Lumopolis laws.",
  ui_story_31210601_88_dialog_content = "I have an obligation to protect the lawful citizens of Lumopolis, including yourself. My actions that day were not rehearsed in any way.",
  ui_story_31210601_89_dialog_content = "On that note, you should know... There's no such organization as the \"Black Rose,\" and I'm no gang boss.",
  ui_story_31210601_90_dialog_content = "As for my \"henchmen,\" if you were paying closer attention, you might've recognized a few of their faces.",
  ui_story_31210601_91_dialog_content = "After taking advantage of us for so long... Don't tell us you don't remember how we look?",
  ui_story_31210601_92_dialog_content = "You people...",
  ui_story_31210601_93_dialog_content = "They're all people from your domain. YOUR people.",
  ui_story_31210601_94_dialog_content = "You damned leech... You're the one who sucked the life out of our lands!",
  ui_story_31210601_95_dialog_content = "Forget our home, you don't even give a damn about our lives! Today we're gonna teach you a lesson that you'll never forget!",
  ui_story_31210601_96_dialog_content = "You penniless rubes... You should be thankful for the opportunity to work for me!",
  ui_story_31210601_97_dialog_content = "If you're so desperate for a fight, allow me to put you back in your place!",
  ui_story_31210601_98_dialog_content = "Men! To me!",
  ui_story_31210601_99_dialog_content = "\"Men\"? You mean these sorry fools?",
  ui_story_31210601_100_dialog_content = "Sorry to disappoint you, but they've been tied up for a while now.",
  ui_story_31210601_101_dialog_content = "(Damn it... Damn it all! It can't end like this! There must be a way...)",
  ui_story_31210601_102_dialog_content = "Wait, Your Honor! Surely, you have no business with a crazy woman like her.",
  ui_story_31210601_103_dialog_content = "Help me leave this place safely, and I will do everything in my power to propel you through the ranks!",
  ui_story_31210601_104_dialog_content = "Even the Chief Judge's position is not outside the question!",
  ui_story_31210601_105_dialog_content = "Oh? What a sudden change of stance.",
  ui_story_31210601_106_dialog_content = "Isn't it your duty to protect the safety and prosperity of the Lumo nobles?",
  ui_story_31210601_107_dialog_content = "This could be your chance to show us your unwavering loyalty! Think about it!",
  ui_story_31210601_108_dialog_content = "So long as they do not attack you, I have no reason to interfere.",
  ui_story_31210601_109_dialog_content = "In addition, I feel I must correct one of your statements.",
  ui_story_31210601_110_dialog_content = "My unwavering loyalty is to the God of Light, and my duty is to uphold justice and order in Lumopolis, not the interests of the noble class.",
  ui_story_31210601_111_dialog_content = "What are you talking about?! They clearly threatened me just now! Weren't you listening?!",
  ui_story_31210601_112_dialog_content = "Or is this \"justice\" you judges love talking about nothing more than empty formalities?!",
  ui_story_31210601_113_dialog_content = "You were safe to make rude comments towards your own citizens before, weren't you?",
  ui_story_31210601_114_dialog_content = "The law applies to everyone equally, and this situation is no different.",
  ui_story_31210601_115_dialog_content = "You're no less of a hypocrite than I am! Especially you, Paloma... You're the worst of all!",
  ui_story_31210601_116_dialog_content = "You speak about hating Lumopolis with all your heart, yet you're willing to conspire with one of their judges!",
  ui_story_31210601_117_dialog_content = "I'm willing to acknowledge my own hypocrisy. Are you?",
  ui_story_31210601_118_dialog_content = "Hmph—!",
  ui_story_31210601_119_dialog_content = "I am nothing like you. Acting polite and kind in front of the nobility, all while treating commoners without an ounce of decency.",
  ui_story_31210601_120_dialog_content = "And I never claimed that what I've done today was for the Lumopolis judge. I did it all for myself.",
  ui_story_31210601_121_dialog_content = "Your actions made me sick to my stomach that day, so I chose to deal with you. It's as simple as that.",
  ui_story_31210601_121X1_dialog_content = "If PlayerName hadn't told me earlier, I would have believed that you truly joined a gang.",
  ui_story_31210601_122_dialog_content = "<color=#e8d9bb>A few hours earlier...</color>",
  ui_story_31210601_123_dialog_content = "Pittman! Over here!",
  ui_story_31210601_124_dialog_content = "PlayerName? What are you doing here?",
  ui_story_31210601_125_dialog_content = "And why are you dressed like a gang member?",
  ui_story_31210601_126_dialog_content = "No time to explain! Just come with me! Hurry!",
  ui_story_31210601_127_dialog_content = "W-Wait! I still have urgent business to attend to!",
  ui_story_31210601_128_dialog_content = "A few days ago, a Lumopolis noble crossed paths with Paloma, and I barely managed to intervene before the situation worsened.",
  ui_story_31210601_129_dialog_content = "But afterward, it didn't seem as though Paloma was ready to let go of the matter... I worry she's about to do something terrible.",
  ui_story_31210601_130_dialog_content = "Which is why I can't go with you right now. Please forgive me.",
  ui_story_31210601_131_dialog_content = "Paloma is the one who asked me to come to find you, Pittman!",
  ui_story_31210601_132_dialog_content = "Oh, and don't forget! You have to pretend to get knocked out by me later; make it look real so it doesn't look like an act!",
  ui_story_31210601_133_dialog_content = "You want me to act...? I don't quite understand... Is this something Paloma cooked up?",
  ui_story_31210601_134_dialog_content = "Don't worry about it! You'll understand everything once you see what happens between Paloma and that noble, okay?",
  ui_story_31210601_135_dialog_content = "She won't do anything illegal, I promise! I trust her, and you trust me... Right?",
  ui_story_31210601_136_dialog_content = "Even though I had mentally prepared myself, I was still somewhat shocked the moment I stepped inside.",
  ui_story_31210601_137_dialog_content = "Really? What about you, PlayerName?",
  ui_story_31210601_138_option_content = "It's all thanks to your disguise.",
  ui_story_31210601_139_dialog_content = "That outfit really emphasizes your cool and imposing presence.",
  ui_story_31210601_140_dialog_content = "Even though I was standing right next to you, I could've sworn I was standing alongside a real gang boss!",
  ui_story_31210601_141_option_content = "Your personality carried the show.",
  ui_story_31210601_142_dialog_content = "It felt as though you were born to play the leader of the Black Roses.",
  ui_story_31210601_143_dialog_content = "Even I had a hard time remembering that you weren't a vicious gang leader!",
  ui_story_31210601_144_dialog_content = "It doesn't help that this outfit appears to be straight out of your personal wardrobe.",
  ui_story_31210601_145_dialog_content = "Hmph. You're beginning to sound like an actual crony with all of that flattery.",
  ui_story_31210601_146_dialog_content = "I have to say, though... that outfit really suits you as well, PlayerName.",
  ui_story_31210601_147_dialog_content = "Are you sure you don't want to stay as my right-hand man?",
  ui_story_31210601_148_dialog_content = "H-Huh?!",
  ui_story_31210601_149_dialog_content = "*Chuckling* I'm only joking.",
  ui_story_31210601_150_dialog_content = "Besides, I work better on my own. I would never do something as stupid or troublesome as joining a gang.",
  ui_story_31210601_151_dialog_content = "The fact that you never intended to attack that nobleman shows that you've matured quite a lot, Paloma.",
  ui_story_31210601_152_dialog_content = "Who, him? Please, he was an easy mark. Besides, I didn't feel like getting my thorns dirty.",
  ui_story_31210601_153_dialog_content = "Though I'm just as surprised that someone as stubborn and nosy as you stood quietly to the side while it all happened. You've matured a bit too, Pittman.",
  ui_story_31210601_154_dialog_content = "I simply chose to trust you and PlayerName this time... as well as my own ability to respond quickly, if the situation called for it.",
  ui_story_31210601_155_dialog_content = "Also, I had no desire to arrest you myself, which is why I wouldn't have let you do anything illegal in front of me.",
  ui_story_31210601_156_dialog_content = "Pretty confident in yourself, aren't you, Your Honor?",
  ui_story_31210601_157_dialog_content = "Those people outside dressed in white must be from the Hall of Justice.",
  ui_story_31210601_158_dialog_content = "Your reinforcements came quicker than I thought.",
  ui_story_31210601_159_dialog_content = "She wasn't kidding. The street is full of Lumo Guards!",
  ui_story_31210601_160_dialog_content = "You mean you didn't call them?",
  ui_story_31210601_161_dialog_content = "No, I didn't. Did you?",
  ui_story_31210601_162_dialog_content = "Was it her?",
  ui_story_31210601_163_dialog_content = "Paloma's gone...",
  ui_story_31210601_164_dialog_content = "So... this is the Black Rose, huh?",
  ui_story_31210601_165_dialog_content = "How very much like her.",
  ui_story_31210602_1_dialog_content = "Ah... those luminescent eyes, the face gifted by the gods... it's like beholding a deity!",
  ui_story_31210602_2_dialog_content = "How splendid, the deity I venerate... my goddess...!",
  ui_story_31210602_3_dialog_content = "Ah... How refreshing the sea breeze is!",
  ui_story_31210602_4_dialog_content = "Every time I go to the beach, I feel so happy. So, what should I do now?",
  ui_story_31210602_5_option_content = "Pick up beautiful shells",
  ui_story_31210602_6_dialog_content = "I might be able to decorate the Colossus with some of these beautiful shells.",
  ui_story_31210602_7_dialog_content = "There are quite a lot of them here. It looks like I've hit the jackpot.",
  ui_story_31210602_8_option_content = "Lie in the sand",
  ui_story_31210602_9_dialog_content = "The sand here is so delicate and soft, I can't help but want to lie down on it.",
  ui_story_31210602_10_dialog_content = "Huh? What's this black spike in the sand? Someone might hurt themselves on it... I guess I should really pull it out.",
  ui_story_31210602_11_dialog_content = "What are you doing?",
  ui_story_31210602_12_dialog_content = "Whoa?! What were you doing down there in the sand?",
  ui_story_31210602_13_dialog_content = "I was just lying here enjoying the sunshine until you started pulling at my swimsuit.",
  ui_story_31210602_14_dialog_content = "S-Sorry, I thought it was some kind of spike...",
  ui_story_31210602_15_dialog_content = "If you really want to apologize, I'd like you to accompany me somewhere.",
  ui_story_31210602_16_dialog_content = "Uh... Where?",
  ui_story_31210602_17_dialog_content = "Have you heard of the mysterious sect here that worships the Firethorn Goddess?",
  ui_story_31210602_18_dialog_content = "The Firethorn Goddess? Never heard of her.",
  ui_story_31210602_19_dialog_content = "Mundane people just love to create such false little gods.",
  ui_story_31210602_20_dialog_content = "The intelligence I have acquired indicates that something is off about this sect, and I plan to investigate it.",
  ui_story_31210602_21_dialog_content = "That sounds kind of dangerous. I'll go with you.",
  ui_story_31210602_22_dialog_content = "But before we depart, I'll need to change into my regular clothes.",
  ui_story_31210602_23_dialog_content = "Hey, what do you two think you're doing? Outsiders aren't welcome here! Away with you!",
  ui_story_31210602_24_dialog_content = "<size=30>What do we do now? They won't let us in...</size>",
  ui_story_31210602_25_dialog_content = "<size=30>Don't worry, leave this to me.</size>",
  ui_story_31210602_26_dialog_content = "We're new members of the flock and would like to participate in today's ceremony.",
  ui_story_31210602_27_dialog_content = "New blood, eh? Do you have any proof? Do you carry the sigil of the Firethorn Goddess?",
  ui_story_31210602_28_dialog_content = "The sigil of the Firethorn Goddess?",
  ui_story_31210602_29_dialog_content = "This—",
  ui_story_31210602_30_dialog_content = "(He just pulled out a short piece of sharp thorn. I guess the jig is up, there's no way we're getting past him!)",
  ui_story_31210602_31_dialog_content = "Is this what you're talking about?",
  ui_story_31210602_32_dialog_content = "(Huh? Paloma actually has one of those?)",
  ui_story_31210602_33_dialog_content = "That's right. This is the gift bestowed on us by the Firethorn Goddess—a gift only true believers can possess.",
  ui_story_31210602_34_dialog_content = "You should've shown it to me sooner. You may enter.",
  ui_story_31210602_35_dialog_content = "How did you get that sigil thing?",
  ui_story_31210602_36_dialog_content = "Guess.",
  ui_story_31210602_37_dialog_content = "You made it with your powers.",
  ui_story_31210602_38_dialog_content = "I guess you're not that dull after all.",
  ui_story_31210602_39_dialog_content = "It's such a coincidence that you can manipulate thorns... It's a good thing the sigil wasn't a bar of chocolate.",
  ui_story_31210602_40_dialog_content = "Do you really believe it was a coincidence?",
  ui_story_31210602_41_dialog_content = "What?",
  ui_story_31210602_42_dialog_content = "It looks like the ceremony hasn't started yet. Let's find somewhere we can watch it from the shadows.",
  ui_story_31210602_43_dialog_content = "It's so dim here. I thought all religious ceremonies took place in bright, open spaces.",
  ui_story_31210602_44_dialog_content = "Not all churches follow the light. Perhaps we'll only find mysterious incantations and offerings here, or maybe even sacrifices...",
  ui_story_31210602_45_dialog_content = "Don't scare me, I don't wanna get served up like a lamb on the altar.",
  ui_story_31210602_46_dialog_content = "Don't worry. This rabble don't have the gall to sacrifice the living just yet.",
  ui_story_31210602_47_dialog_content = "True believers, welcome to today's ceremony. I am the messenger of the Pastor.",
  ui_story_31210602_48_dialog_content = "Today, we offer our most precious sacrifice to the Firethorn Goddess—an expression of our love and admiration for her.",
  ui_story_31210602_49_dialog_content = "Praise the Firethorn Goddess! Praise the Pastor!",
  ui_story_31210602_50_dialog_content = "I see we have some fresh faces among us here today. Of course, we welcome the addition of fresh blood, but first you'll need to present us with your offerings.",
  ui_story_31210602_51_dialog_content = "Only after being approved by our arbiters can you officially join us.",
  ui_story_31210602_52_dialog_content = "What kind of offerings? They're not gonna do anything to us, right?",
  ui_story_31210602_53_dialog_content = "Let's see what the others do first.",
  ui_story_31210602_54_dialog_content = "I have an offering! I want to present it!",
  ui_story_31210602_55_dialog_content = "A passionate acolyte. Excellent! Please join me on the stage.",
  ui_story_31210602_56_dialog_content = "This is a photo I took of a starfish. I think it's very beautiful and perfect for expressing my respect for the Firethorn Goddess.",
  ui_story_31210602_57_dialog_content = "A starfish? You wish to offer a starfish to the Firethorn Goddess? Do you think a mere starfish would touch her heart?",
  ui_story_31210602_58_dialog_content = "Uh, actually, I think the starfish he snapped is really cute.",
  ui_story_31210602_59_dialog_content = "Have you forgotten the focus of our current teachings? Do you really believe that the Pastor would like to see something so mediocre and uninteresting? Next.",
  ui_story_31210602_60_dialog_content = "Hello everyone. The photo I want to share with you is of a sea turtle, which is a type of...",
  ui_story_31210602_61_dialog_content = "Zero points.",
  ui_story_31210602_62_dialog_content = "Zero points.",
  ui_story_31210602_63_dialog_content = "Five points. It's a great shot. Turtles have a very long lifespan. They must hold many stories and secrets.",
  ui_story_31210602_64_dialog_content = "Turtles are just slow, boring reptiles. You can get these photos absolutely anywhere. They're worthless.",
  ui_story_31210602_65_dialog_content = "We were a marine biology photography club, and even though now we're a—",
  ui_story_31210602_66_dialog_content = "Quiet! Next!",
  ui_story_31210602_67_dialog_content = "Some of these judges are really harsh, but so far, it seems this church is basically just a bunch of sea life photographers.",
  ui_story_31210602_68_dialog_content = "They each possess a small piece of firethorn. What, pray tell, does this have to do with sea creatures?",
  ui_story_31210602_69_dialog_content = "Well... I guess there's no connection there.",
  ui_story_31210602_70_dialog_content = "So, there's definitely something deeper going on with this sect.",
  ui_story_31210602_71_dialog_content = "Anyway, the fun's just about to begin.",
  ui_story_31210602_72_dialog_content = "What do you mean?",
  ui_story_31210602_73_dialog_content = "The lights have dimmed, the gates have been shut, and the blue candle lit... Ah, this false ceremony of blessed chicanery is about to begin.",
  ui_story_31210602_74_dialog_content = "The great Pastor has arrived, let us all welcome him with the warmest applause!",
  ui_story_31210602_75_dialog_content = "Praise the Firethorn Goddess! Praise the Pastor!",
  ui_story_31210602_76_dialog_content = "Thank you all for coming to our monthly offering ceremony. The almighty Firethorn Goddess looks forward to receiving the pure offerings you have gathered here to offer up.",
  ui_story_31210602_77_dialog_content = "(Pure offerings? Does he mean gold and jewelry or something like that?)",
  ui_story_31210602_78_dialog_content = "Your Holiness, please allow me to say a few words. We have just assessed the offerings brought by several of the newcomers and have found them to be severely lacking!",
  ui_story_31210602_79_dialog_content = "But I don't want to be too harsh on them. Obviously, they have failed to grasp the rules of the ceremony and need some time to assimilate to our ways.",
  ui_story_31210602_80_dialog_content = "Now, we shall begin our showcase of the true offerings. Behold!",
  ui_story_31210602_81_dialog_content = "Oh, this is breathtaking.",
  ui_story_31210602_82_dialog_content = "The illumination and composition are flawless, almost impeccable!",
  ui_story_31210602_83_dialog_content = "I've also prepared an offering for the Firethorn Goddess! These are candid shots I took of several girls on the beach!",
  ui_story_31210602_84_dialog_content = "Wow! Just look at your offerings! They really are something special! The Firethorn Goddess is going to love these!",
  ui_story_31210602_85_dialog_content = "This is sick! These guys are nothing more than peeping toms! What a bunch of perverts!",
  ui_story_31210602_86_dialog_content = "Pastor, please! Let us gaze upon the Firethorn Goddess once more!",
  ui_story_31210602_87_dialog_content = "Very well. The time has come to invite the Goddess to the altar for all of you to worship.",
  ui_story_31210602_88_dialog_content = "Greetings, Goddess—",
  ui_story_31210602_89_dialog_content = "Huh? The Firethorn Goddess is... a photo?",
  ui_story_31210602_90_dialog_content = "What are these crisscrossing black lines in the photo? I don't get it, but somehow it seems familiar...",
  ui_story_31210602_91_dialog_content = "So, it was him!",
  ui_story_31210602_92_dialog_content = "Huh? You found something?",
  ui_story_31210602_93_dialog_content = "My thorns will soon choke the life out of this broken temple of desire and sin.",
  ui_story_31210602_94_dialog_content = "Fresh blood, do you now understand what kind of photos you must take?",
  ui_story_31210602_95_dialog_content = "Well, this is all rather bizarre, but it seems very exciting at the same time. I am willing to join!",
  ui_story_31210602_96_dialog_content = "I feel a trifle embarrassed due to my advanced years, but I am also willing to follow the Pastor and the Firethorn Goddess!",
  ui_story_31210602_97_dialog_content = "Why aren't those two newcomers in the corner saying anything? You haven't presented any offerings yet, have you? Now you can have the Pastor guide you himself.",
  ui_story_31210602_98_dialog_content = "Oh no, they've noticed us.",
  ui_story_31210602_99_dialog_content = "Here, you can take this photo as an offering.",
  ui_story_31210602_100_dialog_content = "Hmm? Isn't that—!",
  ui_story_31210602_101_dialog_content = "Hurry now! Don't waste the Pastor's time!",
  ui_story_31210602_102_dialog_content = "Um, I... This photo...",
  ui_story_31210602_103_dialog_content = "Let me see—",
  ui_story_31210602_104_dialog_content = "I-Isn't this the Firethorn Goddess?!",
  ui_story_31210602_105_dialog_content = "Who are you? How could you possibly have a photo of the Firethorn Goddess?!",
  ui_story_31210602_106_dialog_content = "Do you know where we can find the Firethorn Goddess? Someone! Anyone! Seize him!",
  ui_story_31210602_107_dialog_content = "I don't know a thing...",
  ui_story_31210602_108_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_109_dialog_content = "How dare you lay hands on him!",
  ui_story_31210602_110_dialog_content = "Good heavens! It's the Firethorn Goddess! She has descended!",
  ui_story_31210602_111_dialog_content = "(How did Paloma change her clothes so quickly?)",
  ui_story_31210602_112_dialog_content = "It's time for this absurd farce to come to an end.",
  ui_story_31210602_113_dialog_content = "Urgh! What fierce thorns! Could this be the true nature of the Firethorn Goddess I pray to?",
  ui_story_31210602_114_dialog_content = "Goddess, I'm your most loyal follower! It's the highest honor to be in your presence!",
  ui_story_31210602_115_dialog_content = "Shut your trap!",
  ui_story_31210602_116_dialog_content = "Aaaaaahhhh!",
  ui_story_31210602_117_dialog_content = "Is this the way the Goddess and the Pastor are supposed to get along? This all seems a bit too intense for me...",
  ui_story_31210602_118_dialog_content = "That's not it. She's my friend, not the Goddess of your twisted little sect. You've all been tricked by the Pastor.",
  ui_story_31210602_119_dialog_content = "It hurts, it hurts! I think I'm about to die!",
  ui_story_31210602_120_dialog_content = "Are you willing to reveal the truth behind this so-called sect now? Give it to me from the top.",
  ui_story_31210602_121_dialog_content = "*Sobbing* I'll tell you! I'll tell you everything!",
  ui_story_31210602_122_dialog_content = "This sect was originally a marine life photography society. I was just one of the members, but my true interest is difficult to articulate...",
  ui_story_31210602_123_dialog_content = "Under my influence, this small club slowly transformed into an eccentric assembly.",
  ui_story_31210602_124_dialog_content = "A few months ago, on the beach, I took a photo of you wearing a divine swimsuit, and I've longed to see it again ever since.",
  ui_story_31210602_125_dialog_content = "When I presented your picture at our photography meetup, everyone started to marvel at your divine beauty—like that of a goddess.",
  ui_story_31210602_126_dialog_content = "I was struggling with money issues back then... Well, no, I wanted to charge the members, t-to sustain the development of the society!",
  ui_story_31210602_127_dialog_content = "So I used your photos to create a series of tales about the Firethorn Goddess, and we gradually developed into what we have today...",
  ui_story_31210602_128_dialog_content = "Such a story behind the establishment of the church. I need to record it in the Book of Doctrines for future believers...",
  ui_story_31210602_129_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_130_dialog_content = "Oh, no! The Book of Doctrines has been whipped to pieces!",
  ui_story_31210602_131_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_132_dialog_content = "Urgh! Such a savage beating! What pain!",
  ui_story_31210602_133_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_134_dialog_content = "Goddess, calm your rage! Please, Goddess, please stop whipping me! Ahhhh!",
  ui_story_31210602_135_dialog_content = "<color=#e8d9bb>Swoosh! Smack!</color>",
  ui_story_31210602_136_dialog_content = "Shameful desire has consumed your soul and reason. Your so-called doctrines are just a mask of hypocrisy.",
  ui_story_31210602_137_dialog_content = "If you continue with this shameless perversion, true judgment will tear you apart without mercy!",
  ui_story_31210602_138_dialog_content = "Ahh! Stop with the lashes! We won't take sneaky pics of hot girls anymore, I swear to the Fireth—No, I swear to the God of Light!",
  ui_story_31210602_139_dialog_content = "I swear to the God of Light! I'll never do anything like this ever again!",
  ui_story_31210602_140_dialog_content = "Oh, so you're all from Lumopolis, that explains a lot.",
  ui_story_31210602_141_dialog_content = "Phew, we finally handed over those creeps to the Hall of Justice.",
  ui_story_31210602_142_dialog_content = "Paloma mentioned wanting to go to the beach to relax. I should go find her... She might need a little cheering up after the whole thing.",
  ui_story_31210602_143_dialog_content = "(Paloma's... watching a little starfish?)",
  ui_story_31210602_144_dialog_content = "(From the looks of her blissful expression, it seems like she's enjoying being alone. I'd better not disturb her.)",
  ui_story_31210602_145_dialog_content = "Did you come all the way here just to leave?",
  ui_story_31210602_146_dialog_content = "I didn't want to disturb you, so...",
  ui_story_31210602_147_dialog_content = "Has everything been taken care of?",
  ui_story_31210602_148_dialog_content = "Yeah, the Hall of Justice has already started the investigation.",
  ui_story_31210602_149_dialog_content = "Thank you so much for everything. I'm lucky I had you around to help me handle the insufferable bother of dealing with the Hall of Justice.",
  ui_story_31210602_150_dialog_content = "What are friends for? Are you feeling better now?",
  ui_story_31210602_151_dialog_content = "It seems you misunderstand me. Do you really see me as the type of person easily rattled by such trivial matters?",
  ui_story_31210602_152_dialog_content = "No, it's just that most people wouldn't feel too good about what happened.",
  ui_story_31210602_153_dialog_content = "Of course, especially the girls who were violated.",
  ui_story_31210602_154_dialog_content = "They originally intended to enjoy a paradisiacal sojourn here, but were maliciously violated by insidious miscreants.",
  ui_story_31210602_155_dialog_content = "Yeah... Good thing you caught the bad guys before those photos went viral.",
  ui_story_31210602_156_dialog_content = "Even if the photos were to spread throughout the continent, it's not those girls who should be made to feel shame and regret, and suffer such outrageous ramifications.",
  ui_story_31210602_157_dialog_content = "I'm curious... What do you think of those people?",
  ui_story_31210602_158_option_content = "They're just an assemblage of pathetic creatures, dominated by base desires.",
  ui_story_31210602_159_option_content = "Those guys are so gross! Yuck!",
  ui_story_31210602_160_dialog_content = "They forged a mask of hypocrisy in the name of a false deity to cover up their own ugliness and contemptuousness.",
  ui_story_31210602_161_dialog_content = "Religion is supposed to be pure and uplifting, with lofty ideals and inspiring hopes for the future, but it is often used by the wicked to poison the world.",
  ui_story_31210602_162_dialog_content = "Hmn! Too right!",
  ui_story_31210602_163_dialog_content = "To be honest, I don't quite understand all those big ideas. I'm actually still a bit worried about you and those photos that guy took of you...",
  ui_story_31210602_164_dialog_content = "Why would you be worried about me? I didn't do anything wrong.",
  ui_story_31210602_165_dialog_content = "I'd never let something like this get the better of me. Nothing is wrong with what I wear, and I feel magnificent.",
  ui_story_31210602_166_dialog_content = "As for those shameless malfeasants, I'll defeat them with honor and integrity, every time!",
  ui_story_31210602_167_dialog_content = "And that's exactly what you did!",
  ui_story_31210602_168_dialog_content = "By the way, this photo you gave to me earlier... Do you want it back?",
  ui_story_31210602_169_dialog_content = "It's a selfie of me wearing a swimsuit. Do you find it unappealing?",
  ui_story_31210602_170_dialog_content = "Of course not. You look so beautiful and confident in this photo.",
  ui_story_31210602_171_dialog_content = "Think of it as a gift from a friend!",
  ui_story_31210602_172_dialog_content = "(This photo of Paloma facing the camera so boldly is simply breathtaking... It's a million times more beautiful than the ones taken without her knowledge from the shadows...)",
  ui_story_31210602_173_dialog_content = "(If only there were some way to stop people from doing things like this... Maybe I can discuss this issue with Paloma in the future...)"
}
return config
